"""Render a local 3D asset for review using Blender, then optionally ask a local vision model for critique."""
from __future__ import annotations
import base64, json, os, subprocess, time, uuid
from pathlib import Path
import httpx
from .config import WORKSPACE_DIR, BLENDER_EXE, OLLAMA_BASE_URL, OLLAMA_MODEL
from .agent import safe_workspace_path
from .autodetect import detect_tools
ROOT=(WORKSPACE_DIR/'omniforge_assets'/'visual_reviews').resolve(); ROOT.mkdir(parents=True,exist_ok=True)
SUPPORTED={'.glb','.gltf','.fbx','.obj','.ply','.stl','.blend'}

def inspect_visual(relative_model_path: str) -> dict:
    rel=Path(relative_model_path.replace('\\','/'))
    if rel.is_absolute() or '..' in rel.parts: raise ValueError('Model path must stay inside the workspace.')
    model=safe_workspace_path(str(rel))
    if not model.is_file() or model.suffix.lower() not in SUPPORTED: raise ValueError('Choose an existing supported 3D model inside the workspace.')
    blender=BLENDER_EXE or detect_tools().get('blender_exe')
    if not blender or not Path(blender).is_file(): return {'status':'BLOCKED','model_path':str(rel),'reason':'Blender is not installed or detected; visual preview cannot be rendered.','next_step':'Install Blender or configure BLENDER_EXE.','metadata_only':True}
    job=uuid.uuid4().hex; out=ROOT/f'{job}.png'; report=ROOT/f'{job}.json'; script=ROOT/f'{job}.py'
    # Script is generated by OmniForge; model path is serialized into it rather than interpolated as code.
    payload={'model':str(model),'output':str(out),'report':str(report)}
    script.write_text("""import bpy, json, math\nfrom mathutils import Vector\ncfg=json.loads(%r)\nbpy.ops.object.select_all(action='SELECT'); bpy.ops.object.delete(use_global=False)\nmodel=cfg['model']; ext=model.lower().rsplit('.',1)[-1]\nif ext=='blend': bpy.ops.wm.open_mainfile(filepath=model)\nelif ext in ('glb','gltf'): bpy.ops.import_scene.gltf(filepath=model)\nelif ext=='fbx': bpy.ops.import_scene.fbx(filepath=model)\nelif ext=='obj':\n try: bpy.ops.wm.obj_import(filepath=model)\n except: bpy.ops.import_scene.obj(filepath=model)\nelif ext=='stl':\n try: bpy.ops.wm.stl_import(filepath=model)\n except: bpy.ops.import_mesh.stl(filepath=model)\nelif ext=='ply':\n try: bpy.ops.wm.ply_import(filepath=model)\n except: bpy.ops.import_mesh.ply(filepath=model)\nmeshes=[o for o in bpy.context.scene.objects if o.type=='MESH']\nif not meshes: raise RuntimeError('No mesh objects found after import')\npts=[]\nfor o in meshes:\n for v in o.bound_box: pts.append(o.matrix_world @ Vector(v))\nlo=Vector((min(p.x for p in pts),min(p.y for p in pts),min(p.z for p in pts))); hi=Vector((max(p.x for p in pts),max(p.y for p in pts),max(p.z for p in pts))); center=(lo+hi)*0.5; span=max((hi-lo).length,0.01)\nscene=bpy.context.scene; scene.render.engine='BLENDER_EEVEE_NEXT' if 'BLENDER_EEVEE_NEXT' in bpy.types.RenderSettings.bl_rna.properties['engine'].enum_items.keys() else 'BLENDER_EEVEE'\nscene.render.resolution_x=900; scene.render.resolution_y=900; scene.render.resolution_percentage=100; scene.render.image_settings.file_format='PNG'; scene.render.filepath=cfg['output']; scene.world.color=(0.045,0.045,0.045)\nfor o in list(scene.objects):\n if o.type in {'LIGHT','CAMERA'}: bpy.data.objects.remove(o,do_unlink=True)\nld=bpy.data.lights.new('OmniForge Key','AREA'); lo=bpy.data.objects.new('OmniForge Key',ld); scene.collection.objects.link(lo); lo.location=center+Vector((span*1.4,-span*1.8,span*1.6)); ld.energy=1700; ld.shape='DISK'; ld.size=span\ncd=bpy.data.cameras.new('OmniForge Review Camera'); cam=bpy.data.objects.new('OmniForge Review Camera',cd); scene.collection.objects.link(cam); cam.location=center+Vector((span*1.7,-span*2.2,span*1.25)); cam.rotation_euler=(center-cam.location).to_track_quat('-Z','Y').to_euler(); cd.lens=50; scene.camera=cam\nscene.render.image_settings.color_mode='RGBA'; bpy.ops.render.render(write_still=True)\nreport={'model':model,'preview':cfg['output'],'mesh_objects':len(meshes),'vertices':sum(len(o.data.vertices) for o in meshes),'faces':sum(len(o.data.polygons) for o in meshes),'bounds':{'min':list(lo),'max':list(hi)},'rendered':True,'review_required':True}\nopen(cfg['report'],'w',encoding='utf-8').write(json.dumps(report,indent=2))\n""" % json.dumps(payload),encoding='utf-8')
    try:
        p=subprocess.run([str(blender),'--background','--python',str(script)],capture_output=True,text=True,timeout=360,shell=False)
        if p.returncode!=0 or not out.is_file(): return {'status':'FAILED','model_path':str(rel),'error':(p.stderr or p.stdout)[-5000:],'exit_code':p.returncode}
        data=json.loads(report.read_text(encoding='utf-8')); data['status']='SUCCEEDED'; data['preview_path']=str(out.relative_to(WORKSPACE_DIR)).replace('\\','/'); data['report_path']=str(report.relative_to(WORKSPACE_DIR)).replace('\\','/')
        try:
            raw=base64.b64encode(out.read_bytes()).decode('ascii'); base=OLLAMA_BASE_URL.split('/v1')[0].rstrip('/')
            with httpx.Client(timeout=90) as client:
                r=client.post(base+'/api/chat',json={'model':OLLAMA_MODEL,'stream':False,'messages':[{'role':'user','content':'Review this rendered 3D asset preview. Return a concise JSON-like critique with visible silhouette issues, framing, obvious mesh defects, and next recommended action. Do not claim to see hidden geometry.','images':[raw]}]})
                if r.is_success: data['local_vision_review']=r.json().get('message',{}).get('content','')
                else: data['vision_review_status']='Local Ollama endpoint did not accept image input.'
        except Exception as e: data['vision_review_status']='Preview rendered; local vision critique unavailable: '+str(e)[:240]
        return data
    except subprocess.TimeoutExpired: return {'status':'FAILED','error':'Blender preview render exceeded six minutes.'}
    finally:
        try: script.unlink(missing_ok=True)
        except Exception: pass
